def factorize(n: int) -> List[int]:
    prime_factors = []
    divisor = 2

    while divisor * divisor <= n:
        while (n % divisor) == 0:
            prime_factors.append(divisor)
            n = int(n / divisor)

        divisor += 1

    if n > 1:
        prime_factors.append(int(n))

    return prime_factors

