def reverse_vowels(s):
    vowels = "aeiouAEIOU"
    result = list(s)
    left, right = 0, len(result)-1

    while left < right:
        while left <= len(result)-1 and result[left] not in vowels:
            left += 1
        while right >= 0 and result[right] not in vowels:
            right -= 1

        if left > right:
            break

        result[left], result[right] = result[right], result[left]
        left += 1
        right -= 1

    return "".join(result)

def reverse_vowels(s):
    """Reverse only the vowels in the given string."""
    vowels = "aeiouAEIOU"  # Define the set of all lowercase and uppercase vowels.
    result = list(s)  # Convert string into a list for easy modification.
    left, right = 0, len(result) - 1

    while left < right:  # Loop until the pointers meet or cross each other.
        while (
            left <= len(result) - 1 and result[left] not in vowels
        ):  # Move the left pointer to the right while skipping consonants.
            left += 1
        while (
            right >= 0 and result[right] not in vowels
        ):  # Move the right pointer to the left while skipping consonants.
            right -= 1

        if (
            left > right
        ):  # If both pointers have crossed each other, break out of the loop as no more vowels can be reversed.
            break

        result[left], result[right] = (
            result[right],
            result[left],
        )  # Swap the vowels at the current positions.
        left += 1
        right -= 1

    return "".join(result)  # Convert list back to string and return.

